I7.B(null,iJ,function(){var a=Bh(q(X),new R(null,2,5,S,[CE,Ut],null)),b=kH.g(q(X)),c=z.h(a,mV(b));return l(a)?tAa(a,I([Dw,function(){Q.l(X,xg,new R(null,2,5,S,[CE,Ut],null),null);c&&(Q.l(X,M,hM,null),Q.l(X,M,kH,null));return I7.h(aI,null)},tF,function(d){Q.l(X,xg,new R(null,2,5,S,[CE,Ut],null),null);return M8(IG,"Failed to delete version",d)}])):null});var P8=new CSSStyleSheet;P8.replaceSync("/* Dataset Modal Styles */\n\n.dataset-modal-backdrop {\n  position: absolute;\n  inset: 0;\n  background: var(--modeling-modal-backdrop);\n  display: flex;\n  align-items: flex-start;\n  justify-content: center;\n  padding-top: 80px;\n  z-index: 1200;\n}\n\n.dataset-modal {\n  background: var(--modeling-overlay-bg);\n  border: none;\n  border-radius: 8px;\n  width: 100%;\n  max-width: 500px;\n  max-height: calc(100% - 160px);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  box-shadow: var(--modeling-shadow-xl);\n}\n\n/* Search bar */\n.dataset-modal-search {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 12px 16px;\n  border-bottom: 1px solid var(--modeling-overlay-border);\n}\n\n.dataset-modal-search .sy-icon {\n  color: var(--sy-text-mm);\n}\n\n.dataset-modal-search input {\n  flex: 1;\n  border: none;\n  outline: none;\n  font-size: 14px;\n  background: transparent;\n  color: var(--sy-text-p);\n}\n\n.dataset-modal-search input::placeholder {\n  color: var(--sy-text-mm);\n}\n\n/* Content wrapper - fixed height container */\n.dataset-modal-content {\n  flex: 0 0 350px;\n  overflow-y: auto;\n}\n\n/* Dataset list */\n.dataset-item {\n  display: flex;\n  align-items: center;\n  padding: 12px 16px;\n  cursor: pointer;\n  border-bottom: 1px solid var(--modeling-overlay-border);\n  transition: background 0.15s ease;\n}\n\n.dataset-item:hover {\n  background: var(--modeling-overlay-bg-hover);\n}\n\n/* Keyboard cursor (arrow keys / Enter from the search field). Distinct from\n   :hover by the accent rail so a mouse resting on the list can't be mistaken\n   for the row Enter would open. */\n.dataset-item.highlighted {\n  background: var(--modeling-overlay-bg-hover);\n  box-shadow: inset 2px 0 0 var(--sy-accent);\n}\n\n.dataset-item.highlighted .dataset-item-name {\n  color: var(--sy-accent);\n}\n\n.dataset-item:last-child {\n  border-bottom: none;\n}\n\n.dataset-item-info {\n  flex: 1;\n  min-width: 0;\n}\n\n.dataset-item-actions {\n  display: flex;\n  align-items: center;\n  gap: 2px;\n  flex-shrink: 0;\n}\n\n.dataset-delete-btn,\n.dataset-access-btn {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: none;\n  border: none;\n  cursor: pointer;\n  padding: 4px;\n  color: var(--sy-text-mm);\n  opacity: 0;\n  transition:\n    opacity 0.15s,\n    color 0.15s;\n  flex-shrink: 0;\n}\n\n.dataset-item:hover .dataset-delete-btn,\n.dataset-item:hover .dataset-access-btn {\n  opacity: 0.5;\n}\n\n.dataset-delete-btn:hover {\n  opacity: 1 !important;\n  color: var(--modeling-removed-text);\n}\n\n.dataset-access-btn:hover {\n  opacity: 1 !important;\n  color: var(--sy-text-p);\n}\n\n.dataset-delete-confirm {\n  display: flex;\n  gap: 6px;\n  flex-shrink: 0;\n}\n\n/* Destructive action — confirm Delete. Uses the *hover* shade of the\n   removed colour family because the base shade (--modeling-removed-stroke)\n   is a pale pink meant for borders/diff backgrounds, not as a button\n   fill. That made the button look disabled. Hover further darkens. */\n.dataset-delete-confirm .confirm-yes {\n  padding: 4px 12px;\n  border-radius: 4px;\n  border: none;\n  background: var(--modeling-removed-stroke-hover, #c0392b);\n  color: var(--modeling-button-text, #fff);\n  font-size: 12px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background .15s, transform .05s;\n}\n.dataset-delete-confirm .confirm-yes:hover {\n  background: #a82d2d;\n}\n.dataset-delete-confirm .confirm-yes:active {\n  transform: translateY(1px);\n}\n.dataset-delete-confirm .confirm-yes:disabled {\n  background: var(--modeling-removed-stroke, #fadada);\n  cursor: not-allowed;\n  opacity: .6;\n}\n\n.dataset-delete-confirm .confirm-no {\n  padding: 4px 12px;\n  border-radius: 4px;\n  border: 1px solid var(--modeling-overlay-border);\n  background: transparent;\n  color: var(--sy-text);\n  font-size: 12px;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n.dataset-item-name {\n  font-weight: 500;\n  font-size: 14px;\n  color: var(--sy-text-p);\n  margin-bottom: 4px;\n}\n\n.dataset-item-meta {\n  display: flex;\n  gap: 16px;\n  font-size: 12px;\n  color: var(--sy-text-m);\n}\n\n.dataset-item-meta span {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n}\n\n/* Empty state */\n.dataset-modal-empty {\n  height: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  color: var(--sy-text-m);\n}\n\n/* Footer */\n.dataset-modal-footer {\n  border-top: 1px solid var(--modeling-overlay-border);\n}\n\n/* Primary-action pattern (shared with versions Save + deploy): accent bg,\n   hover shifts to accent-hover (brighter in dark / deeper in light) —\n   never opacity tricks, they turn near-white buttons muddy on dark. */\n.dataset-modal-footer button {\n  width: 100%;\n  padding: 14px 16px;\n  border: none;\n  background: var(--sy-accent);\n  color: var(--modeling-button-text);\n  font-size: 14px;\n  font-weight: 500;\n  cursor: pointer;\n  transition: background 0.15s ease;\n}\n\n.dataset-modal-footer button:hover {\n  background: var(--sy-accent-hover);\n}\n\n.dataset-modal-footer button:disabled {\n  background: var(--sy-accent-tint);\n  color: var(--sy-text-m);\n  cursor: not-allowed;\n}\n\n/* \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\n   Access view (owners + access groups)\n   \x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d\x3d */\n\n.dataset-access-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 12px 16px;\n  border-bottom: 1px solid var(--modeling-overlay-border);\n}\n\n.dataset-access-close {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: none;\n  border: none;\n  cursor: pointer;\n  padding: 4px;\n  margin-left: auto;\n  border-radius: 4px;\n  color: var(--sy-text-m);\n  transition: background 0.15s, color 0.15s;\n}\n\n.dataset-access-close:hover {\n  background: var(--modeling-hover-overlay);\n  color: var(--sy-text-p);\n}\n\n.dataset-access-title {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  min-width: 0;\n}\n\n.dataset-access-title-label {\n  font-size: 11px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--sy-text-m);\n}\n\n.dataset-access-title-name {\n  font-size: 14px;\n  font-weight: 500;\n  color: var(--sy-text-p);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/* Owners / Access groups tabs — same idiom as the import popover */\n.dataset-access-tabs {\n  display: flex;\n  gap: 4px;\n  padding: 10px 16px 0;\n}\n\n/* Fixed height — the count badge is taller than the label, so letting the\n   tab size to its content made it grow the moment a binding appeared. */\n.dataset-access-tab {\n  flex: 1;\n  height: 36px;\n  box-sizing: border-box;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  padding: 0 10px;\n  border: none;\n  border-radius: 6px;\n  background: transparent;\n  color: var(--sy-text-m);\n  font-size: 12px;\n  font-weight: 500;\n  font-family: inherit;\n  cursor: pointer;\n  transition: background 0.15s ease, color 0.15s ease;\n}\n\n.dataset-access-tab .sy-icon {\n  color: currentColor;\n}\n\n.dataset-access-tab:hover {\n  background: var(--modeling-overlay-bg-hover);\n}\n\n.dataset-access-tab.active {\n  background: var(--sy-accent);\n  color: var(--modeling-button-text);\n}\n\n/* Bound-count badge — reads at a glance which tab actually has bindings */\n.dataset-access-count {\n  min-width: 17px;\n  padding: 0 5px;\n  border-radius: 9px;\n  background: var(--sy-accent-tint);\n  color: var(--sy-text-p);\n  font-size: 10px;\n  font-weight: 700;\n  line-height: 17px;\n  text-align: center;\n}\n\n.dataset-access-tab.active .dataset-access-count {\n  background: var(--modeling-hover-overlay-strong);\n  color: var(--modeling-button-text);\n}\n\n/* Zero count keeps its box (no reflow), just goes invisible. */\n.dataset-access-count.empty {\n  visibility: hidden;\n}\n\n/* box-sizing so the border/padding stay inside the 100% width — without it\n   the input overflowed its container and the right edge clipped. */\n.dataset-access-search-wrap {\n  padding: 12px 16px 8px;\n}\n\n.dataset-access-search-wrap input {\n  width: 100%;\n  box-sizing: border-box;\n  padding: 8px 10px;\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 6px;\n  background: transparent;\n  color: var(--sy-text-p);\n  font-size: 13px;\n  font-family: inherit;\n  outline: none;\n}\n\n.dataset-access-search-wrap input::placeholder {\n  color: var(--sy-text-mm);\n}\n\n.dataset-access-search-wrap input:focus {\n  border-color: var(--sy-accent);\n}\n\n.dataset-access-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 7px 16px;\n  cursor: pointer;\n  color: var(--sy-text);\n  transition: background 0.15s;\n}\n\n.dataset-access-row:hover {\n  background: var(--modeling-overlay-bg-hover);\n}\n\n.dataset-access-row .sy-icon {\n  color: var(--sy-text-mm);\n  flex-shrink: 0;\n}\n\n.dataset-access-row.selected {\n  color: var(--sy-text-p);\n}\n\n.dataset-access-row.selected .sy-icon {\n  color: var(--sy-text-p);\n}\n\n.dataset-access-check {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 16px;\n  height: 16px;\n  border: 1px solid var(--modeling-overlay-border);\n  border-radius: 4px;\n  flex-shrink: 0;\n  color: var(--modeling-button-text);\n}\n\n.dataset-access-row.selected .dataset-access-check {\n  background: var(--sy-accent);\n  border-color: var(--sy-accent);\n}\n\n.dataset-access-row.selected .dataset-access-check .sy-icon {\n  color: var(--modeling-button-text);\n}\n\n.dataset-access-label {\n  font-size: 13px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.dataset-access-empty {\n  padding: 4px 16px 12px;\n  font-size: 12px;\n  color: var(--sy-text-mm);\n}\n\n/* Unbound dataset warning — sits above the save button in the footer.\n   Fixed height and faded (not removed) when irrelevant, so toggling the\n   last binding never resizes the modal. */\n.dataset-access-warning {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  height: 32px;\n  box-sizing: border-box;\n  padding: 0 16px;\n  font-size: 11.5px;\n  color: var(--sy-warn);\n  background: var(--sy-warn-tint);\n  transition: opacity 0.15s ease;\n}\n\n.dataset-access-warning.hidden {\n  opacity: 0;\n  pointer-events: none;\n}\n");
